    @Override
    public void balance(DidaTradeMain.BalanceRequest request, StreamObserver<DidaTradeMain.BalanceReply> responseObserver) {
        if (!this.server_state.beforeRequest(responseObserver)) {
            return;
        }
        // for debug purposes
        System.out.println("Receiving balance request:" + request);

        int reqid = request.getReqid();
        int uid   = request.getUserid();

        // for debug purposes
        System.out.println("reqid " + reqid + " userid " + uid);

        DidaTradeMain.BalanceReply response;
        try {
            response = this.server_state.readCausalBalance(
                    reqid, uid, request.getMinVersion());

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            responseObserver.onError(
                    io.grpc.Status.CANCELLED
                            .withDescription("Balance interrupted while waiting")
                            .asRuntimeException());
            return;

        } catch (io.grpc.StatusRuntimeException e) {
            responseObserver.onError(e);
            return;
        }

        System.out.println("Result is ready for balance request with reqid " + reqid);

        responseObserver.onNext(response);
        responseObserver.onCompleted();
    }

